window.roroSubmitButton=function(buttonId=null,formId=null){if(!formId||!buttonId)return;const form=$("#"+formId),button=$("#"+buttonId);if(button.prop("type")!=="submit")return;roroShowOverlay(!0);const processAjax=()=>{if(!form[0].reportValidity()){roroShowOverlay(!1);return}const formData=new FormData(form[0]);$.ajax({url:form.attr("action"),type:(form.attr("method")||"POST").toUpperCase(),data:formData,contentType:!1,processData:!1}).done(response=>form.trigger("roro:ajax:success",[response])).fail((xhr,status,error)=>{form.trigger("roro:ajax:error",[xhr,status,error]),button.data("ajax-errors")&&xhr.responseJSON?.errors&&populateFormErrors(form,xhr.responseJSON.errors)}).always(()=>roroShowOverlay(!1))},processClassic=()=>{form[0].reportValidity()?form.submit():roroShowOverlay(!1)};button.data("ajax")?processAjax():processClassic()},window.roroRegisterButtonOnClick=function(buttonId){const button=$("#"+buttonId);button.length&&button.on("click",function(event){event.preventDefault(),roroSubmitButton(button.attr("id"),button.data("form-id"))})},window.roroShowOverlay=function(show=!0){const overlay=$("#roro-form-overlay");overlay.length&&(show?overlay.fadeIn(150):overlay.fadeOut(150))},window.populateFormErrors=function(form,errors){clearFormErrors(form);for(let[inputName,messages]of Object.entries(errors)){inputName=normalizeInputName(inputName);const input=form.find(`[name="${inputName}"]`);input.length&&roroShowError(input.attr("id"),messages.join(", "),!0)}},window.clearFormErrors=function(form){form.find(".roro-input").each(function(){roroShowError($(this).attr("id"),"",!1)})},$(document).ready(function(){$(".roro-btn-submit").each(function(){roroRegisterButtonOnClick($(this).attr("id"))}),$(".roro-border-error").each(function(){manageBorderError($(this))})});
